use leptos::prelude::*;

use crate::class::cn;

// Generated by build.rs from icons/icons.toml; lookup tables repeat the same values.
#[allow(clippy::match_same_arms)]
mod generated {
    include!(concat!(env!("OUT_DIR"), "/icons_gen.rs"));
}
pub use generated::IconName;

/// Inline SVG icon from the vendored, allowlisted sets. Decorative (`aria-hidden`) unless a
/// `label` is given, then it is announced as an image.
#[component]
pub fn Icon(
    name: IconName,
    #[prop(into, optional)] class: MaybeProp<String>,
    #[prop(into, optional)] label: MaybeProp<String>,
) -> impl IntoView {
    let labelled = move || label.get().is_some();
    view! {
        <svg
            xmlns="http://www.w3.org/2000/svg"
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            stroke-width="2"
            stroke-linecap="round"
            stroke-linejoin="round"
            data-icon=name.name()
            class=move || cn(&["size-4 shrink-0", &class.get().unwrap_or_default()])
            aria-hidden=move || if labelled() { None } else { Some("true") }
            role=move || labelled().then_some("img")
            aria-label=move || label.get()
            focusable="false"
            inner_html=name.body()
        ></svg>
    }
}
